-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["modules/phoenix/lua/quests/assault_limits.lua"]={["Path"]="modules/phoenix/lua/quests/assault_limits.lua",["SHA256"]="58ac41221a21a78102e477241b9166383e4de6f13506dc9506b7086834dfbc74",["Text"]="-----------------------------------\n-- Module: Assault Mission and Promotion Limits\n-- Only Private Second Class Assaults are available. Promotions stop at Superior Private.\n-- No Promotion: Captain block yet because the quest is not yet implemented, so it cannot be called.\n-- Players receive a message at the Assault counter NPCs telling them the current limits of available assaults.\n-- Players receive a message at Abquhbah telling them the current promotion limits.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('assault_limits')\n\nlocal maxAssaultRank   = xi.assault.mercenaryRank.PRIVATE_SECOND_CLASS\nlocal maxPromotionRank = xi.assault.mercenaryRank.SUPERIOR_PRIVATE\nlocal missionRanks     = {}\nlocal instanceRanks    = {}\n\n-- Every quest in the chain, so a GM-flagged one goes nowhere either.\nlocal promotionQuests =\n{\n    [xi.assault.mercenaryRank.PRIVATE_FIRST_CLASS] = 'scripts/quests/ahtUrhgan/Promotion_Private_First_Class',\n    [xi.assault.mercenaryRank.SUPERIOR_PRIVATE   ] = 'scripts/quests/ahtUrhgan/Promotion_Superior_Private',\n    [xi.assault.mercenaryRank.LANCE_CORPORAL     ] = 'scripts/quests/ahtUrhgan/Promotion_Lance_Corporal',\n    [xi.assault.mercenaryRank.CORPORAL           ] = 'scripts/quests/ahtUrhgan/Promotion_Corporal',\n    [xi.assault.mercenaryRank.SERGEANT           ] = 'scripts/quests/ahtUrhgan/Promotion_Sergeant',\n    [xi.assault.mercenaryRank.SERGEANT_MAJOR     ] = 'scripts/quests/ahtUrhgan/Promotion_Sergeant_Major',\n    [xi.assault.mercenaryRank.CHIEF_SERGEANT     ] = 'scripts/quests/ahtUrhgan/Promotion_Chief_Sergeant',\n    [xi.assault.mercenaryRank.SECOND_LIEUTENANT  ] = 'scripts/quests/ahtUrhgan/Promotion_Second_Lieutenant',\n    [xi.assault.mercenaryRank.FIRST_LIEUTENANT   ] = 'scripts/quests/ahtUrhgan/Promotion_First_Lieutenant',\n}\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    for assaultArea, missions in pairs(xi.assault.missionsByArea) do\n        if assaultArea ~= xi.assault.assaultArea.NYZUL_ISLE then\n            for rank, missionId in ipairs(missions) do\n                missionRanks[missionId] = rank\n            end\n        end\n    end\n\n    for missionName, instanceId in pairs(xi.assault.instance) do\n        instanceRanks[instanceId] = missionRanks[xi.assault.mission[missionName]]\n    end\n\n    for rank, questPath in pairs(promotionQuests) do\n        if rank > maxPromotionRank then\n            xi.module.modifyInteractionEntry(questPath, function(quest)\n                -- Every section, not just the offer. First Lieutenant is offered by a trigger area with no NPC key.\n                for _, section in ipairs(quest.sections) do\n                    section.check = function()\n                        return false\n                    end\n                end\n            end)\n        end\n    end\nend)\n\nm:addOverride('xi.zones.Aht_Urhgan_Whitegate.npcs.Abquhbah.onTrigger', function(player, npc)\n    if xi.besieged.getMercenaryRank(player) >= maxPromotionRank then\n        player:printToPlayer('You have reached the current promotion limit: Superior Private. Only Private Second Class Assault missions are currently available.', xi.msg.channel.SYSTEM_3)\n    end\n\n    super(player, npc)\nend)\n\nm:addOverride('xi.assault.onMissionGiverTrigger', function(player, npc, eventOffset, assaultArea)\n    player:printToPlayer('Only Private Second Class Assault missions are currently available. The highest rank you can earn is Superior Private.', xi.msg.channel.SYSTEM_3)\n\n    local rank = math.min(xi.besieged.getMercenaryRank(player), maxAssaultRank)\n    if rank == 0 then\n        return super(player, npc, eventOffset, assaultArea)\n    end\n\n    local active = xi.extravaganza.campaignActive()\n    local cipher = 0\n\n    if\n        active == xi.extravaganza.campaign.SPRING_FALL or\n        active == xi.extravaganza.campaign.BOTH\n    then\n        cipher = 1\n    end\n\n    player:startEvent(eventOffset, rank, player:hasKeyItem(xi.keyItem.IMPERIAL_ARMY_ID_TAG) and 1 or 0,\n        player:getAssaultPoint(assaultArea), player:getCurrentAssault(), cipher)\nend)\n\nm:addOverride('xi.assault.onMissionGiverEventFinish', function(player, csid, option, npc, eventOffset, assaultArea)\n    if csid == eventOffset and bit.band(option, 0xF) == 1 then\n        local rank = missionRanks[bit.rshift(option, 4)]\n        if\n            not rank or\n            rank > maxAssaultRank or\n            rank > xi.besieged.getMercenaryRank(player)\n        then\n            return\n        end\n    end\n\n    super(player, csid, option, npc, eventOffset, assaultArea)\nend)\n\nm:addOverride('xi.assault.checkRequirements', function(player, content)\n    local rank = missionRanks[content.assaultID]\n    if rank and rank > maxAssaultRank then\n        return false\n    end\n\n    return super(player, content)\nend)\n\nm:addOverride('xi.instance.onEventUpdate', function(player, csid, option, npc)\n    local rank = instanceRanks[player:getLocalVar('INSTANCE_ID')]\n    if rank and rank > maxAssaultRank then\n        player:instanceEntry(npc, 1)\n        return false\n    end\n\n    return super(player, csid, option, npc)\nend)\n"},["modules/phoenix/lua/quests/hiddenquests/anniversary_ring.lua"]={["Path"]="modules/phoenix/lua/quests/hiddenquests/anniversary_ring.lua",["SHA256"]="d183ebe0e09df3fd35fcd4b5b813e12ba85b1a47fdec26cbc5735663b1f8f7c0",["Text"]="-----------------------------------\n-- Module: Anniversary Ring for New Characters\n-- Hands out an Anniversary Ring with the Adventurer's Coupon at the end of the opening cutscene.\n-- Changing nations replays that cutscene, so only a character's first viewing grants the ring.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('anniversary_ring')\n\nlocal introEvents =\n{\n    [xi.zone.BASTOK_MARKETS]     = 7,\n    [xi.zone.BASTOK_MINES]       = 1,\n    [xi.zone.PORT_BASTOK]        = 1,\n    [xi.zone.NORTHERN_SAN_DORIA] = 535,\n    [xi.zone.SOUTHERN_SAN_DORIA] = 503,\n    [xi.zone.PORT_SAN_DORIA]     = 500,\n    [xi.zone.WINDURST_WATERS]    = 531,\n    [xi.zone.WINDURST_WOODS]     = 367,\n    [xi.zone.PORT_WINDURST]      = 305,\n}\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    xi.module.modifyInteractionEntry('scripts/quests/hiddenQuests/New_Character_Cutscenes', function(quest)\n        for zoneId, eventId in pairs(introEvents) do\n            local zoneSection = quest.sections[1][zoneId]\n            local baseHandler = zoneSection and zoneSection.onEventFinish[eventId]\n\n            -- A missing handler would leave the whole cutscene unregistered, taking the coupon with it.\n            if baseHandler then\n                zoneSection.onEventFinish[eventId] = function(player, csid, option, npc)\n                    -- The base handler marks the nation, so the first viewing is read ahead of it.\n                    local firstViewing = quest:getVar(player, 'nations') == 0\n                    local result       = baseHandler(player, csid, option, npc)\n\n                    if firstViewing then\n                        npcUtil.giveItem(player, xi.item.ANNIVERSARY_RING)\n                    end\n\n                    return result\n                end\n            end\n        end\n    end)\nend)\n"},["modules/phoenix/lua/zones/era_guild_shared_stocks.lua"]={["Path"]="modules/phoenix/lua/zones/era_guild_shared_stocks.lua",["SHA256"]="edf8fc55e2f4003b30cd6785ac059058aef1c09c7e14b0b0433b14ef61c4a8bc",["Text"]="-----------------------------------\n-- Era Guild Shared Stocks\n-- A module to link guild shops to share stocks\n-----------------------------------\nrequire('modules/module_utils')\nrequire('scripts/globals/guild_shops')\n-----------------------------------\nlocal m = Module:new('era_guild_shared_stocks')\n\nm:addOverride('xi.zones.Metalworks.npcs.Vicious_Eye.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.METALWORKS].text.VICIOUS_EYE_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Northern_San_dOria.npcs.Lucretia.onTrigger', function(player, npc)\n    local ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, ID.text.LUCRETIA_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Mhaura.npcs.Mololo.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.MHAURA].text.SMITHING_GUILD)\n    end\nend)\n\nm:addOverride('xi.zones.Bastok_Markets.npcs.Teerth.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.BASTOK_MARKETS].text.TEERTH_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Mhaura.npcs.Celestina.onTrigger', function(player, npc)\n    xi.guildShops.onTrigger(player, npc)\nend)\n\nm:addOverride('xi.zones.Windurst_Waters.npcs.Chomo_Jinjahl.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.WINDURST_WATERS].text.CHOMOJINJAHL_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Southern_San_dOria.npcs.Cletae.onTrigger', function(player, npc)\n    local ID = zones[xi.zone.SOUTHERN_SAN_DORIA]\n\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, ID.text.CLETAE_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Windurst_Woods.npcs.Meriri.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.WINDURST_WOODS].text.MERIRI_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Bastok_Mines.npcs.Odoba.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.BASTOK_MINES].text.ODOBA_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Windurst_Woods.npcs.Retto-Marutto.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.WINDURST_WOODS].text.RETTO_MARUTTO_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Selbina.npcs.Gibol.onTrigger', function(player, npc)\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.SELBINA].text.CLOTHCRAFT_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Northern_San_dOria.npcs.Cauzeriste.onTrigger', function(player, npc)\n    local ID = zones[xi.zone.NORTHERN_SAN_DORIA]\n\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, ID.text.CAUZERISTE_SHOP_DIALOG)\n    end\nend)\n\n-----------------------------------\n-- Neptune's Spire Tenshodo guild vendors\n-- Akamafula and Amalasanda were converted to normal shops on retail.\n-- This reverts them back to being guild shops, while also keeping the tenshodo membership anti-cheat\n-- that was already in place on their files.\n-----------------------------------\nm:addOverride('xi.zones.Lower_Jeuno.npcs.Akamafula.onTrigger', function(player, npc)\n    if not player:hasKeyItem(xi.keyItem.TENSHODO_MEMBERS_CARD) then\n        return -- Anti-Cheat.\n    end\n\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.LOWER_JEUNO].text.AKAMAFULA_SHOP_DIALOG)\n    end\nend)\n\nm:addOverride('xi.zones.Lower_Jeuno.npcs.Amalasanda.onTrigger', function(player, npc)\n    if not player:hasKeyItem(xi.keyItem.TENSHODO_MEMBERS_CARD) then\n        return -- Anti-Cheat.\n    end\n\n    if xi.guildShops.onTrigger(player, npc) then\n        player:showText(npc, zones[xi.zone.LOWER_JEUNO].text.AMALASANDA_SHOP_DIALOG)\n    end\nend)\n"},["scripts/enum/quest_log.lua"]={["Path"]="scripts/enum/quest_log.lua",["SHA256"]="9dce4b45f2b054d3ba6a6975a19c59493534f9844e97f9a171f97f0e910e9290",["Text"]="xi = xi or {}\n\n---@enum xi.questLog\nxi.questLog =\n{\n    NONE        = -1,\n    SANDORIA    =  0,\n    BASTOK      =  1,\n    WINDURST    =  2,\n    JEUNO       =  3,\n    OTHER_AREAS =  4,\n    OUTLANDS    =  5,\n    AHT_URHGAN  =  6,\n    CRYSTAL_WAR =  7,\n    ABYSSEA     =  8,\n    ADOULIN     =  9,\n    COALITION   = 10,\n}\n"},["scripts/globals/interaction/hidden_quest.lua"]={["Path"]="scripts/globals/interaction/hidden_quest.lua",["SHA256"]="5a2f7718bfb253c6295d540bda7b5ec6533310e02a543f276b29fbe986aac3a5",["Text"]="-----------------------------------\n-- HiddenQuest class\n-----------------------------------\nrequire('scripts/globals/interaction/container')\n-----------------------------------\n\nHiddenQuest = setmetatable({ area = {} }, { __index = Container })\nHiddenQuest.__index = HiddenQuest\n\n---@diagnostic disable-next-line: duplicate-set-field\nHiddenQuest.__eq = function(q1, q2)\n    return q1.name == q2.name\nend\n\nHiddenQuest.reward = {}\n\n---@diagnostic disable-next-line: duplicate-set-field\nfunction HiddenQuest:new(name)\n    local obj = Container:new('HQuest[' .. name .. ']')\n    setmetatable(obj, self)\n\n    obj.name = name\n    return obj\nend\n\n-----------------------------------\n-- HiddenQuest operations\n-----------------------------------\n\nfunction HiddenQuest:complete(player)\n    local gaveReward = npcUtil.giveReward(player, self.reward)\n    if gaveReward then\n        self:cleanup(player)\n    end\n\n    return gaveReward\nend\n"},["scripts/globals/interaction/quest.lua"]={["Path"]="scripts/globals/interaction/quest.lua",["SHA256"]="a282effab61157d345b3dcf22007821c92937a725c33ea966b6488451a2fcf08",["Text"]="-----------------------------------\n-- Quest class\n-----------------------------------\nrequire('scripts/globals/interaction/container')\n-----------------------------------\n---@see TInteractionContainer\n---@class TQuest : TInteractionContainer\n---@field areaId xi.questLog\n---@field questId integer\nQuest = setmetatable({ areaId = 0 }, { __index = Container })\nQuest.__index = Quest\n\nQuest.__eq = function(q1, q2)\n    return q1.areaId == q2.areaId and q1.questId == q2.questId\nend\n\n---@type rewardParam\nQuest.reward = {}\n\n---@type TQuestSection[]\nQuest.sections = {}\n\n---@nodiscard\n---@param areaId xi.questLog\n---@param questId integer\n---@return TQuest\nfunction Quest:new(areaId, questId)\n    local obj = Container:new(Quest.getVarPrefix(areaId, questId))\n    setmetatable(obj, self)\n    obj.areaId = areaId\n    obj.questId = questId\n    return obj\nend\n\n---@nodiscard\n---@param areaId xi.questLog\n---@param questId integer\n---@return string\nfunction Quest.getVarPrefix(areaId, questId)\n    return string.format('Quest[%d][%d]', areaId, questId)\nend\n\n---@nodiscard\n---@param player CBaseEntity\n---@return table<xi.questStatus>\nfunction Quest:getCheckArgs(player)\n    return { player:getQuestStatus(self.areaId, self.questId) }\nend\n\n-----------------------------------\n-- Quest operations\n-----------------------------------\n\n---@param player CBaseEntity\n---@return nil\nfunction Quest:begin(player)\n    player:addQuest(self.areaId, self.questId)\nend\n\n---@param player CBaseEntity\n---@return boolean\nfunction Quest:complete(player)\n    local didComplete = npcUtil.completeQuest(player, self.areaId, self.questId, self.reward)\n    if didComplete then\n        self:cleanup(player)\n    end\n\n    return didComplete\nend\n"},["scripts/globals/quests.lua"]={["Path"]="scripts/globals/quests.lua",["SHA256"]="fff090277ca33ac77e39817c7fb20a279535866ba84f264ddddcf34c88d70650",["Text"]="-----------------------------------\n--- +         : The quest is coded and completeable but might not be fully fleshed out and accurate.\n--- Converted : The \"Original\" implementation in NPC files has been removed and replaced with Interaction Framework files. Implies \"Implemented\", but doesn't necesserily imply \"Verified\".\n-----------------------------------\n\nxi = xi or {}\nxi.quest = xi.quest or {}\n\n-----------------------------------\n--\n--  QUESTS ID\n--\n-----------------------------------\n\nxi.quest.area =\n{\n    [xi.questLog.SANDORIA]    = 'sandoria',\n    [xi.questLog.BASTOK]      = 'bastok',\n    [xi.questLog.WINDURST]    = 'windurst',\n    [xi.questLog.JEUNO]       = 'jeuno',\n    [xi.questLog.OTHER_AREAS] = 'otherAreas',\n    [xi.questLog.OUTLANDS]    = 'outlands',\n    [xi.questLog.AHT_URHGAN]  = 'ahtUrhgan',\n    [xi.questLog.CRYSTAL_WAR] = 'crystalWar',\n    [xi.questLog.ABYSSEA]     = 'abyssea',\n    [xi.questLog.ADOULIN]     = 'adoulin',\n    [xi.questLog.COALITION]   = 'coalition',\n}\n\nxi.quest.id =\n{\n    -----------------------------------\n    --  San d'Oria - 0\n    -----------------------------------\n    [xi.quest.area[xi.questLog.SANDORIA]] =\n    {\n        A_SENTRYS_PERIL                 = 0,  -- + Converted\n        WATERS_OF_THE_CHEVAL            = 1,  -- + Converted\n        ROSEL_THE_ARMORER               = 2,  -- + Converted\n        THE_PICKPOCKET                  = 3,  -- + Converted\n        FATHER_AND_SON                  = 4,  -- + Converted\n        THE_SEAMSTRESS                  = 5,  -- + Converted\n        THE_DISMAYED_CUSTOMER           = 6,  -- + Converted\n        THE_TRADER_IN_THE_FOREST        = 7,  -- + Converted\n        THE_SWEETEST_THINGS             = 8,  -- + Converted\n        THE_VICASQUES_SERMON            = 9,  -- + Converted\n        A_SQUIRES_TEST                  = 10, -- + Converted\n        GRAVE_CONCERNS                  = 11, -- + Converted\n        THE_BRUGAIRE_CONSORTIUM         = 12, -- + Converted\n        LIZARD_SKINS                    = 15, -- + Converted\n        FLYERS_FOR_REGINE               = 16, -- +\n        GATES_TO_PARADISE               = 18, -- +\n        A_SQUIRES_TEST_II               = 19, -- + Converted\n        TO_CURE_A_COUGH                 = 20, -- +\n        TIGERS_TEETH                    = 23, -- + Converted\n        UNDYING_FLAMES                  = 26, -- +\n        A_PURCHASE_OF_ARMS              = 27, -- + Converted\n        A_KNIGHTS_TEST                  = 29, -- + Converted\n        THE_MEDICINE_WOMAN              = 30, -- + Converted\n        BLACK_TIGER_SKINS               = 31, -- + Converted\n        GROWING_FLOWERS                 = 58, -- + Converted\n        TRIAL_BY_ICE                    = 59, -- +\n        THE_GENERALS_SECRET             = 60, -- + Converted\n        THE_RUMOR                       = 61, -- + Converted\n        HER_MAJESTYS_GARDEN             = 62, -- + Converted\n        INTRODUCTION_TO_TEAMWORK        = 63, -- + Converted\n        INTERMEDIATE_TEAMWORK           = 64, -- + Converted\n        ADVANCED_TEAMWORK               = 65, -- + Converted\n        GRIMY_SIGNPOSTS                 = 66, -- + Converted\n        A_JOB_FOR_THE_CONSORTIUM        = 67, -- + Converted\n        TROUBLE_AT_THE_SLUICE           = 68, -- + Converted\n        THE_MERCHANTS_BIDDING           = 69, -- + Converted\n        UNEXPECTED_TREASURE             = 70,\n        BLACKMAIL                       = 71, -- + Converted\n        THE_SETTING_SUN                 = 72, -- + Converted\n        DISTANT_LOYALTIES               = 74, -- + Converted\n        THE_RIVALRY                     = 75, -- + Converted\n        THE_COMPETITION                 = 76, -- + Converted\n        STARTING_A_FLAME                = 77, -- + Converted\n        FEAR_OF_THE_DARK                = 78, -- + Converted\n        WARDING_VAMPIRES                = 79, -- + Converted\n        SLEEPLESS_NIGHTS                = 80, -- + Converted\n        LUFETS_LAKE_SALT                = 81, -- + Converted\n        HEALING_THE_LAND                = 82, -- +\n        SORCERY_OF_THE_NORTH            = 83, -- +\n        THE_CRIMSON_TRIAL   