     ANALYZE_CIRDAS_CAVERNS          = 62,\n        ANALYZE_OUTER_RAKAZNAR          = 63,\n        PRESERVE_CEIZAK_BATTLEGROUNDS   = 64,\n        PRESERVE_YAHSE_HUNTING_GROUNDS  = 65,\n        PRESERVE_FORET_DE_HENNETIEL     = 66,\n        PRESERVE_MORIMAR_BASALT_FIELDS  = 67,\n        PRESERVE_YORCIA_WEALD           = 68,\n        PRESERVE_MARJAMI_RAVINE         = 69,\n        PRESERVE_KAMIHR_DRIFTS          = 70,\n        PRESERVE_CIRDAS_CAVERNS         = 71,\n        PRESERVE_OUTER_RAKAZNAR         = 72,\n        PATROL_RALA_WATERWAYS           = 73,\n        PATROL_SIH_GATES                = 74,\n        PATROL_MOH_GATES                = 75,\n        PATROL_CIRDAS_CAVERNS           = 76,\n        PATROL_DHO_GATES                = 77,\n        PATROL_WOH_GATES                = 78,\n        PATROL_OUTER_RAKAZNAR           = 79,\n        RECOVER_CEIZAK_BATTLEGROUNDS    = 80,\n        RECOVER_FORET_DE_HENNETIEL      = 81,\n        RECOVER_MORIMAR_BASALT_FIELDS   = 82,\n        RECOVER_YORCIA_WEALD            = 83,\n        RECOVER_MARJAMI_RAVINE          = 84,\n        RECOVER_KAMIHR_DRIFTS           = 85,\n        RESEARCH_RALA_WATERWAYS         = 86,\n        RESEARCH_CEIZAK_BATTLEGROUNDS   = 87,\n        RESEARCH_FORET_DE_HENNETIEL     = 88,\n        RESEARCH_MORIMAR_BASALT_FIELDS  = 89,\n        RESEARCH_YORCIA_WEALD           = 90,\n        RESEARCH_MARJAMI_RAVINE         = 91,\n        RESEARCH_KAMIHR_DRIFTS          = 92,\n        BOOST_FORET_DE_HENNETIEL        = 93,\n        BOOST_MARJAMI_RAVINE            = 94,\n        BOOST_KAMIHR_DRIFTS             = 95,\n    }\n}\n\nlocal function getVarPrefix(areaId, questId)\n    return string.format('Quest[%d][%d]', areaId, questId)\nend\n\nxi.quest.getVarPrefix = getVarPrefix\n\n-- Interaction Framework Helper Functions\nxi.quest.incrementVar = function(player, areaId, questId, name, value)\n    return player:incrementCharVar(getVarPrefix(areaId, questId) .. name, value)\nend\n\nxi.quest.getVar = function(player, areaId, questId, name)\n    return player:getVar(getVarPrefix(areaId, questId) .. name)\nend\n\nxi.quest.setVar = function(player, areaId, questId, name, value, expiry)\n    return player:setVar(getVarPrefix(areaId, questId) .. name, value, expiry)\nend\n\nxi.quest.setVarExpiration = function(player, areaId, questId, name, expiry)\n    return player:setCharVarExpiration(getVarPrefix(areaId, questId) .. name, expiry)\nend\n\nxi.quest.getLocalVar = function(player, areaId, questId, name)\n    return player:getLocalVar(getVarPrefix(areaId, questId) .. name)\nend\n\nxi.quest.setLocalVar = function(player, areaId, questId, name, value)\n    return player:setLocalVar(getVarPrefix(areaId, questId) .. name, value)\nend\n\nxi.quest.getMustZone = function(player, areaId, questId)\n    return player:getCharVar(getVarPrefix(areaId, questId) .. 'mustZone') ~= 0 and true or false\nend\n\nxi.quest.setMustZone = function(player, areaId, questId)\n    player:setCharVar(getVarPrefix(areaId, questId) .. 'mustZone', player:getZoneID())\nend\n"},["scripts/quests/abyssea/A_Beaked_Blusterer.lua"]={["Path"]="scripts/quests/abyssea/A_Beaked_Blusterer.lua",["SHA256"]="ae98a4400d57d6d6fbf9fe4b5b77732d613b486c3bbeb2d46d6de16035bfcbba",["Text"]="-----------------------------------\n-- A_Beaked_Blusterer\n-----------------------------------\n-- !addquest 8 176\n-- Cavernous Maw    : !pos 340.000 -0.500 -680.000 107\n-- Bennu            : !spawnmob 17670554\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_BEAKED_BLUSTERER)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTH_GUSTABERG] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.BENNU_DEPLUMER)\n        end,\n\n        [xi.zone.SOUTH_GUSTABERG] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 1\n            end,\n\n            onEventUpdate =\n            {\n                [1] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    -- NOTE: Give the key item prior to completing the quest so that we reward the correct\n                    -- KI!  If we complete first, it'll adjust the total completed count, and be off by one!\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Delectable_Demon.lua"]={["Path"]="scripts/quests/abyssea/A_Delectable_Demon.lua",["SHA256"]="07a441f9e75e94311a0981e03e84f3eb8ae107fff36c80c34298a41c46b62957",["Text"]="-----------------------------------\n-- A Delectable Demon\n-----------------------------------\n-- !addquest 8 173\n-- Cavernous Maw    : !pos 367.980 -0.443 -119.874 103\n-- Cirein-croin     : !spawnmob 17662476\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_DELECTABLE_DEMON)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(56)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [56] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.CIREIN_CROIN_HARPOONER)\n        end,\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 57\n            end,\n\n            onEventUpdate =\n            {\n                [57] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Fluttery_Fiend.lua"]={["Path"]="scripts/quests/abyssea/A_Fluttery_Fiend.lua",["SHA256"]="86ce98a2f6a8b108ad4ed43e906fe7fb99c309dacb9370022994eaa5e0771608",["Text"]="-----------------------------------\n-- A Fluttery Fiend\n-----------------------------------\n-- !addquest 8 174\n-- Cavernous Maw    : !pos -344.396 -24.941 52.581 118\n-- Itzpapalotl      : !spawnmob 17658277\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_FLUTTERY_FIEND)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(62)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.ITZPAPALOTL_DECLAWER)\n        end,\n\n        [xi.zone.BUBURIMU_PENINSULA] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 63\n            end,\n\n            onEventUpdate =\n            {\n                [63] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [63] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Goldstruck_Gigas.lua"]={["Path"]="scripts/quests/abyssea/A_Goldstruck_Gigas.lua",["SHA256"]="a46c9b610a02fd5e6f00ec3b04d508ed1e31ff9db3f88e55c9537aee6f2bb69b",["Text"]="-----------------------------------\n-- A Goldstruck Gigas\n-----------------------------------\n-- !addquest 8 163\n-- Cavernous Maw    : !pos -557.900 0.001 637.846 102\n-- Briareus         : !spawnmob 17318446\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(9)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.BRIAREUS_FELLER)\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 10\n            end,\n\n            onEventUpdate =\n            {\n                [10] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    -- NOTE: Give the key item prior to completing the quest so that we reward the correct\n                    -- KI!  If we complete first, it'll adjust the total completed count, and be off by one!\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Journey_Begins.lua"]={["Path"]="scripts/quests/abyssea/A_Journey_Begins.lua",["SHA256"]="b41c5639a83752c122837261b35469e7907a57e3fa412fd4462b72fd5e214f85",["Text"]="-----------------------------------\n-- A Journey Begins\n-----------------------------------\n-- !addquest 8 160\n-- Joachim : !pos -52.844 0 -9.978 246\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_JOURNEY_BEGINS)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.TRAVERSER_STONE1,\n}\n\nquest.sections =\n{\n    -- Retail behavior for this quest is to flag when the expansion has been purchased,\n    -- and is flagged if Abyssea is enabled in onGameIn.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:getMainLvl() >= 30\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(325)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 0 then\n                    return 324\n                end\n            end,\n\n            onEventFinish =\n            {\n                [324] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [325] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n\n                        -- Traverser Stone epoch begins when 'The Truth Beckons' is flagged, and is\n                        -- retail behavior.  This can be confirmed by checking the currency tab on\n                        -- retail servers.\n                        player:setTraverserEpoch()\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_TRUTH_BECKONS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Man-eating_Mite.lua"]={["Path"]="scripts/quests/abyssea/A_Man-eating_Mite.lua",["SHA256"]="ec932bb25a7538a8b458af7cb151df81013c5c450dd48f47ee66c4a4b95931a0",["Text"]="-----------------------------------\n-- A Man-eating Mite\n-----------------------------------\n-- !addquest 8 177\n-- Cavernous Maw    : !pos 270.000 -9.000 -70.000 112\n-- Resheph          : !spawnmob 17813913\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_MAN_EATING_MITE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.XARCABARD] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(58)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [58] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.RESHEPH_ERADICATOR)\n        end,\n\n        [xi.zone.XARCABARD] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 59\n            end,\n\n            onEventUpdate =\n            {\n                [59] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [59] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/A_Sea_Dogs_Summons.lua"]={["Path"]="scripts/quests/abyssea/A_Sea_Dogs_Summons.lua",["SHA256"]="d39807195ad441b87968c1455c421252a96587e8da87fc6eceb5f96e20e33e3b",["Text"]="-----------------------------------\n-- A Sea Dog's Summons\n-----------------------------------\n-- !addquest 8 180\n-- Flagged on completion of Champions of Abyssea.\n-- Zone into the Hall of the Gods between 18:00 and 5:00. Flags Death and Rebirth upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_SEA_DOGS_SUMMONS)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                VanadielHour() >= 18 and\n                VanadielHour() < 5\n        end,\n\n        [xi.zone.HALL_OF_THE_GODS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 6\n            end,\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DEATH_AND_REBIRTH)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Altepa_Dominion_Op_01.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_01.lua",["SHA256"]="ff7528433fb9996a6827f542748c753d3fbb2ffb3f04856ee271d372b3ecea0d",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #01\n-----------------------------------\n-- !addquest 8 87\n-- Dominion Sergeant (Nanaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_01_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            ['Sand_Sweeper'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 560)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Altepa_Dominion_Op_02.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_02.lua",["SHA256"]="108d25b0959fba99432531e4f0779c8a28ddb591e989ed17b14e6546615645b6",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #02\n-----------------------------------\n-- !addquest 8 88\n-- Dominion Sergeant (Nanaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_02_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == x